-- ROOT ONLY, one AAPL NY day / one provider page. No new subscription, purchase or capacity change.
-- Requires an actual successful rollback result and deployed-worker hash/no-fetch authentication probe.
-- Root separately admits Alpaca into the existing bounded budget. This script cannot expand that admission.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='10s';
SET LOCAL timezone='UTC';
SELECT pg_advisory_xact_lock(2026083000261022);
DO $admit$
DECLARE test_evidence jsonb;deploy_evidence jsonb;current_functions jsonb;ad record;tid uuid;h text;payload jsonb;spec jsonb;specsha text;vers jsonb;before_p02 jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton AND owner_id='top3000-recovery-20261023-root-4b1314bcb5c2' AND owner_fence=2 AND stop_generation=0 AND NOT stopped AND enabled AND hold_reason IS NULL AND admitted_until>clock_timestamp()) THEN RAISE EXCEPTION 'OWNER_STOP_OR_ADMISSION_CHANGED';END IF;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton AND enabled AND shared_scheduler_verified AND budget_evidence->>'provider_admissions_allowed'='true' AND budget_evidence->'allowed_providers' ? 'Alpaca' AND (budget_evidence#>>'{resource_limits,max_relation_bytes}')::bigint BETWEEN 1 AND 2000000000) THEN RAISE EXCEPTION 'CURRENT_BOUNDED_ALPACA_ADMISSION_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) THEN RAISE EXCEPTION 'ALL_EXISTING_ATTEMPTS_MUST_FINISH_BEFORE_ADAPTER_TRANSFER';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task t WHERE t.payload->>'kind'='ALPACA_SIP_GAP_BATCH_V1') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.alpaca_sip_source_page_v1) THEN RAISE EXCEPTION 'ALPACA_LANE_ALREADY_STARTED_RECONCILE_PRESERVED_PROGRESS';END IF;
 SELECT details INTO test_evidence FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='ALPACA_SIP_GAP_ROLLBACK_VERIFIED' AND details->>'result'='PASS' AND details->>'provider_accuracy_verified'='false' AND details->>'live_provider_requested'='false' ORDER BY at DESC LIMIT 1;
 current_functions:=(SELECT jsonb_object_agg(fn,encode(sha256(convert_to(pg_get_functiondef(('population_top3000_202608_202609_v1.'||fn)::regprocedure),'UTF8')),'hex')) FROM (VALUES ('alpaca_sip_urlencode_v1(text)'),('alpaca_sip_spec_v1(jsonb)'),('alpaca_sip_context_v1(uuid)'),('alpaca_sip_acquire_v1(uuid,text)'),('alpaca_sip_claim_v1(uuid,text)'),('alpaca_sip_commit_v1(uuid,text,jsonb)'),('alpaca_sip_failure_v1(uuid,text,jsonb)'),('alpaca_sip_timestamp_v1(text)'),('alpaca_sip_number_v1(jsonb)'),('alpaca_sip_parse_page_v1(text,jsonb)'),('alpaca_sip_resource_guard_v1()'),('alpaca_sip_normalize_v1(uuid,text)'),('alpaca_sip_derive_v1(uuid,text)'),('alpaca_sip_quality_hold_v1(uuid,text)'),('price_pipeline_acquire_v2(uuid,text)'),('price_pipeline_normalize_v2(uuid,text)'),('alpaca_sip_code_hash_v1()'),('price_retained_partition_v1(uuid,text)')) h(fn));
 IF test_evidence IS NULL OR test_evidence->'tested_function_sha256' IS DISTINCT FROM current_functions THEN RAISE EXCEPTION 'REAL_ROLLBACK_EVIDENCE_FOR_CURRENT_ALPACA_FUNCTIONS_REQUIRED';END IF;
 SELECT details INTO deploy_evidence FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='ALPACA_SIP_GAP_WORKER_DEPLOYED_VERIFIED' AND details->>'result'='PASS' AND details->>'slug'='population-top3000-bars-v1' AND details->>'worker_sha256'='f895e63fb23f2ee34de31d827ff4b128db37b8b06cd9168e33d7a960785665ad' AND details->>'invalid_token_http_status'='403' AND details->>'provider_requests_during_auth_probe'='0' ORDER BY at DESC LIMIT 1;
 IF deploy_evidence IS NULL THEN RAISE EXCEPTION 'DEPLOYED_WORKER_HASH_AND_NO_FETCH_AUTH_PROBE_REQUIRED';END IF;
 IF position('population-top3000-bars-v1' in pg_get_functiondef('population_top3000_202608_202609_v1.pipeline_dispatch_edge_v1(uuid,text,text)'::regprocedure))=0 THEN RAISE EXCEPTION 'ROOT_REVIEWED_EDGE_SLUG_ALLOWLIST_REQUIRED';END IF;
 IF encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.price_retained_partition_v1(uuid,text)'::regprocedure),'UTF8')),'hex')<>'54ee6c5efb998ef35c9064a8e3767261f9498ab0546f3472675fd4cd3dceb586' THEN RAISE EXCEPTION 'RETAINED_PRICE_HANDLER_CHANGED';END IF;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='P01' AND stage IN('ACQUIRE','NORMALIZE') AND function_oid='population_top3000_202608_202609_v1.price_retained_partition_v1(uuid,text)'::regprocedure::oid AND function_sha256='54ee6c5efb998ef35c9064a8e3767261f9498ab0546f3472675fd4cd3dceb586' AND resource_class='DATABASE' AND provider IS NULL AND enabled)<>2
 OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='P01' AND stage IN('DERIVE','VALIDATE')) THEN RAISE EXCEPTION 'P01_ADAPTERS_CHANGED_REVIEW_BEFORE_TRANSFER';END IF;
 SELECT jsonb_agg(to_jsonb(a) ORDER BY stage) INTO before_p02 FROM population_top3000_202608_202609_v1.pipeline_adapter a WHERE family_id='P02';
 FOR ad IN SELECT * FROM (VALUES ('ACQUIRE','price_pipeline_acquire_v2(uuid,text)','PROVIDER'),('NORMALIZE','price_pipeline_normalize_v2(uuid,text)','DATABASE'),('DERIVE','alpaca_sip_derive_v1(uuid,text)','DATABASE'),('VALIDATE','alpaca_sip_quality_hold_v1(uuid,text)','DATABASE')) v(stage,fn,resource) LOOP
  h:=encode(sha256(convert_to(pg_get_functiondef(('population_top3000_202608_202609_v1.'||ad.fn)::regprocedure),'UTF8')),'hex');
  INSERT INTO population_top3000_202608_202609_v1.pipeline_adapter(family_id,stage,function_oid,function_sha256,resource_class,provider,enabled,reviewed_test_evidence,producer_revision,expected_batch_seconds)
  VALUES('P01',ad.stage,('population_top3000_202608_202609_v1.'||ad.fn)::regprocedure::oid,h,ad.resource,CASE WHEN ad.resource='PROVIDER' THEN 'Alpaca' ELSE NULL END,true,jsonb_build_object('sql_test',test_evidence,'worker_deployment',deploy_evidence,'provider_accuracy_verified',false,'admission','ONE_AAPL_SOURCE_PAGE_PENDING_LIVE_REVIEW','retained_handler_preserved_sha256','54ee6c5efb998ef35c9064a8e3767261f9498ab0546f3472675fd4cd3dceb586'),'alpaca-sip-gap-20261023-v1',45)
  ON CONFLICT(family_id,stage) DO UPDATE SET function_oid=EXCLUDED.function_oid,function_sha256=EXCLUDED.function_sha256,resource_class=EXCLUDED.resource_class,provider=EXCLUDED.provider,enabled=EXCLUDED.enabled,reviewed_test_evidence=EXCLUDED.reviewed_test_evidence,producer_revision=EXCLUDED.producer_revision,expected_batch_seconds=EXCLUDED.expected_batch_seconds;
 END LOOP;
 IF before_p02 IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(a) ORDER BY stage) FROM population_top3000_202608_202609_v1.pipeline_adapter a WHERE family_id='P02') THEN RAISE EXCEPTION 'P02_ADAPTER_TRANSFER_NOT_AUTHORISED';END IF;
 payload:='{"kind":"ALPACA_SIP_GAP_BATCH_V1","symbols":["AAPL"],"start_ny_date":"2026-09-08","end_ny_date_exclusive":"2026-09-09","calendar_scope_id":"corrected_company_scope_8e6ca1178f03822c","max_pages":1,"first_page_review_required":true,"provider_accuracy_verified":false}'::jsonb;
 spec:=population_top3000_202608_202609_v1.alpaca_sip_spec_v1(payload);specsha:=encode(sha256(convert_to(spec::text,'UTF8')),'hex');
 vers:=jsonb_build_object('scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','archive_contract_revision','alpaca-sip-gap-20261023-v1','alpaca_bundle_sha256',population_top3000_202608_202609_v1.alpaca_sip_code_hash_v1(),'request_spec_sha256',specsha);
 tid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('P01','ACQUIRE','alpaca-sip-gap:'||specsha,payload,vers);
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(task_id,event,details) VALUES(tid,'ALPACA_SIP_GAP_FIRST_PAGE_ADMITTED',jsonb_build_object('owner_fence',2,'provider','Alpaca','max_pages',1,'hard_page_ceiling',64,'max_symbols_per_batch',50,'max_calendar_days_per_batch',7,'max_bars_total_per_page',10000,'max_response_bytes',8388608,'worker_sha256','f895e63fb23f2ee34de31d827ff4b128db37b8b06cd9168e33d7a960785665ad','request_spec',spec,'cohort_certified',false,'shared_target_families',jsonb_build_array('P01','P02'),'missing_minutes_filled',0,'quality_requirement','LIVE_SOURCE_PAGE_AND_COMPACT_REPARSE_REVIEW_BEFORE_EXPANDING_WAVE','no_new_subscription',true));
 UPDATE population_top3000_202608_202609_v1.pipeline_control SET next_wakeup_at=clock_timestamp(),wake_reason='TESTED_ALPACA_SIP_ONE_AAPL_PAGE_ADMITTED' WHERE singleton;
 IF EXISTS(SELECT 1 FROM cron.job WHERE jobid=596 AND active) THEN RAISE EXCEPTION 'ROOT_RESUME_MUST_REMAIN_SEPARATE';END IF;
END $admit$;
COMMIT;
